namespace gui_forms {

// PlotAnnotationItem's property capabilities (property-capabilities study, sections
// 2, 14 and 15). Generated by tools/property_codemod.py from
// tools/property_families/plot_annotation_item.json: edit the config, not this file.
//
// Each is a standard-layout struct whose only member is its property's
// cell, taken by the declaring class as a base. A write
// `(*control).x = value;` runs `assign`: the declaring class's
// prepare_write hook (require_mutable first, then the value's checks), the
// compare and store, then the written hook (the touch, side effects and the
// change event, through the protected virtual on_<property>_changed() where
// Windows Forms has an overridable On<Property>Changed; other properties
// have no hook, and a subclass subscribes to their change events instead). A read is
// `(*control).x.read()`.

// The annotation's words.
template <typename Declaring>
struct PlotAnnotationItemTextCapability {
    PropertyCell<std::string, PlotAnnotationItemTextCapability<Declaring>> text{};

    static void assign(PlotAnnotationItemTextCapability& capability, std::string incoming) {
        Declaring& control = static_cast<Declaring&>(capability);
        control.prepare_write(std::as_const(capability.text), incoming);
        if (!capability.text.replace(std::move(incoming))) return;
        control.written(std::as_const(capability.text));
    }
};

// The anchor's x in the first horizontal axis's units.
template <typename Declaring>
struct PlotAnnotationItemXCapability {
    PropertyCell<double, PlotAnnotationItemXCapability<Declaring>> x{0.0};

    static void assign(PlotAnnotationItemXCapability& capability, double incoming) {
        Declaring& control = static_cast<Declaring&>(capability);
        control.prepare_write(std::as_const(capability.x), incoming);
        if (!capability.x.replace(std::move(incoming))) return;
        control.written(std::as_const(capability.x));
    }
};

// The anchor's y in the first vertical axis's units.
template <typename Declaring>
struct PlotAnnotationItemYCapability {
    PropertyCell<double, PlotAnnotationItemYCapability<Declaring>> y{0.0};

    static void assign(PlotAnnotationItemYCapability& capability, double incoming) {
        Declaring& control = static_cast<Declaring&>(capability);
        control.prepare_write(std::as_const(capability.y), incoming);
        if (!capability.y.replace(std::move(incoming))) return;
        control.written(std::as_const(capability.y));
    }
};

// Every PlotAnnotationItem capability, in the order the declaring class takes them.
template <typename Declaring>
struct PlotAnnotationItemCapabilities : public PlotAnnotationItemTextCapability<Declaring>,
                                        public PlotAnnotationItemXCapability<Declaring>,
                                        public PlotAnnotationItemYCapability<Declaring> {};

} // namespace gui_forms
